package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSoDraft2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma Bika Asbahna", "Allow adaa ku gala subixi, adaa galaba gal; Adiga uun baannu ku nool nahay, adaa ku dhimanaynaa, xaggaagaana u ah soo bixin.", "Subaxdii.", "Nebigu ﷺ waxa uu baray saxaabada in ay yidhaahdaan saaka iyo fiidkii."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma Bika Amsayna", "Allow adaa ku galnay maqrib adaa aroorta ku galeynaa; adaan ku noolnahay adaa ku dhimanaynaa, xaggaagaana loo noqon.", "Fiidkii.", "Nebigu ﷺ waxa uu baray saxaabada in ay yidhaahdaan saaka iyo fiidkii."),
        "dua_afiyah_morning" to DuaText("Weydiinta Afiyah", "Allahayow waxaan ku waydiisanayaa cafis iyo wanaag aduun iyo aakhiraba.", "Nabiga ﷺ waligiis ka tagin ducadan, subax iyo galab.", "Qofna lama siin wax ka wanaagsan wanaagga."),
        "dua_afini_fi_badani" to DuaText("Caafimaadka Jirka, Maqalka iyo Aragga", "Allahayow jirkeyga caafimaad sii. Allahayow maqalka ii wanagsan. Allahayow aragayga wanaag ku waafaji. Adiga mooyee ilaah kale ma jiro.", "Saddex jeer subax kasta iyo galab kasta.", "Ducada caafimaadka iyo ilaalinta dareenka."),
        "dua_ya_hayyu_aslih" to DuaText("Amuurahayga oo dhan sax", "Rabbiyow, anoo noolow, arzuqhow, naxariistaada ayaan caawimaad ku doondoonaa, Haddaba ii toosi arrimahayga oo dhan, Oo ha ii dayn nafteyda xataa indho libiqsi aawadeed.", "Nebigu ﷺ waxa uu Faaduma (RA) kula taliyey in ay subax iyo galabba tidhaahdo.", "Arrin kasta oo Alle la garab galo."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Tasbiix Juweyriyah (RA)", "Eebaa ka nasahan, mahad dhammaanteedna isagaa iska leh - inta khalqigiisa ka raalli noqday, oo la mid ah miisaanka Carshigiisa iyo khad kalimadiisa.", "Saddex jeer subaxdii - ka miisaan badan saacadaha dhikrka.", "Afartan weedhood oo la yidhaahdo saddex jeer waxay ka miisaan weyn tahay dikriga laga bilaabo waaberiga ilaa subaxda badhkii."),
        "dua_salawat" to DuaText("Durood-e-Ibraahim", "Allahayow u naxariiso Muxammad ﷺ iyo ehelka Muxamed sidaad ugu soo ducaysay Ibraahim (AS) iyo reer Ibraahim; Adiga ayaa Mahad leh, Sharaf leh. Allahayow u naxariiso Muxammad ﷺ iyo ehelka Muxamed sidaad ugu barakaysay Ibraahim (AS) iyo reer Ibraahim; Adiga ayaa Mahad leh, Sharaf leh.", "Salawaat Nabiga ﷺ ducada iyo wakhti kasta.", "Qofkii hal mar dira, Allaah wuxuu u soo dejiyey toban raxmad (Muslim 408)."),
        "dua_wudu_after" to DuaText("Wudu ka dib", "Waxaan ka marag kacayaa in aan cidina xaq u lahayn in la caabudo Alle mooyee, keligiis, oo aan la wadaagin, Muxammadna ﷺ waa addoonkiisii ​​iyo rasuulkiisii. Allow iga dhig kuwa toobad keena iyo kuwa is daahiriya.", "Ka dib markii ay dhammeeyeen wudu.", "Sideeda albaab ee Jannada ayaa laga furay inuu ka galo siduu doono."),
        "dua_wudu_before" to DuaText("Wudu ka hor", "Magaca Allaah.", "Marka la bilaabayo wudu.", "Ma jiro wuduu (dhamays ah) qofkii aan ku xusin magaca Eebbe korkiisa."),
        "dua_istiftah" to DuaText("Ducada Furitaanka (Sana)", "Subxaanallaah, Allow adiga ayaa mahad leh. Magacaagu waa barakaysan yahay, sharaftaadana waa la sarreeyaa, oo adiga mooyee ilaah kale ma jiro.", "Bilawga salaadda, isla markiiba takbiirta furitaanka.", "Ducada furitaanka sunnada ee salaada."),
        "dua_ruku" to DuaText("Marka la rukuucayo", "Nasahan Eebahaybaa wayn.", "Ugu yaraan saddex jeer rukuuc.", "Sunnada tasbiixda rukuucda."),
        "dua_sujood" to DuaText("Sujuud", "Subxaana Watacaalaa Eebahaa Sarreeya.", "Ugu yaraan saddex jeer sujuud.", "Addoonku wuxuu ugu dhaw yahay Eebihiis isagoo sujuudsan (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Ka soo kaca Ruku", "Eebbana waa maqlaa kii ku mahadiya. Eebbow adigaa mahad oo dhan iska leh.", "Iyadoo rukuuc ka soo kacaysa oo taagan.", "Qofkii 'Rabbana wa lakal-xamd' ku beegma kan Malaa'igta, dembigiisii ​​hore waa loo dhaafaa."),
        "dua_between_sajdas" to DuaText("Labada Sajda dhexdooda", "Eebbow i cafi. Eebbow i cafi.", "Inta u dhaxaysa labada sujuudood.", "Ducada sunnada ee fadhiga u dhexeeya sujuudaha."),
        "dua_before_salam_four" to DuaText("Afar shay oo laga qaxo (Salaan ka hor)", "Rabbiyow, waxaan kaa magan galay cadaabka naarta, cadaabka qabriga, imtixaamaadka nolosha iyo dhimashada, iyo sharka fitnada Masiixa beenta ah (Dajjal).", "Tashahhud iyo salawaat kama dambeys ah ka dib, salaam ka hor.", "Nebigu ﷺ wuxuu amray in laga magan galo afartan shay."),
        "dua_qunoot_witr" to DuaText("Qunuutka salaadda Witr", "Illahow igu hanuuniyo kuwaad hanuunisay, Iga yeel kuwa aad wanaag u siisay ka mid noqo kuwaad daryeeshay, igu barako waxaad siisay, igana ilaali xumaanta waxaad xukmisay. Adigu wax xukumaya, midna kuguma xukumo, Kaad la saaxiibtana ma aha mid la dulleeyo. Rabbiyow adiga ayaa mahad leh oo sarreeya.", "Ducada witriga - Nebigu ﷺ baray Hasan ibn Cali (RA).", "Qunoot Sunnaha witri. (Xanafiyada dhexdooda, 'Allaahumma inna nasta'inuka' sidoo kale waa la yaqaan.)"),
        "dua_qunoot_hanafi" to DuaText("Qunoot (Allahumma Innaa Nasta'inuka)", "Allahayow Gargaarkaada iyo Dambi dhaafkaaga waanu kaa badinaynaa, waanu ku rumaynay oo ku talo saarnay, waxaanu kugu amaanaynaa sida ugu fiican, waanu ku mahadinaynaa, mana nihin kuwo ku mahad-naqsan, cid kasta oo ku caasiyana waan ka tagaynaa. Allow adiga kaliya ayaan ku caabudaynaa, adigaan kuu baryaynaa oo aan u sujuudnay, adigaan kuu soo dagdagaynaa oo ku dadaalaynaa, naxariistaada ayaan rajaynaynaa, ciqaabtaadana waxaan ka cabsanaynaa; 021-047 gaaladana waxaa u sugnaaday cadaabkiinnu.", "In witri - dhaqanka Xanafiyada.", "Waxaa laga soo wariyey Cumar (RA) ee qunoot."),
        "dua_sleep_aslamtu" to DuaText("Erayadii Ugu Dambeeyay Hurdada Ka Hor", "Allow adiga ayaan nafteyda u dhiibaa, Adiga ayaan arrinkayga ku aaminay, dhabarkaygana waxaan u hibeeyay ilaalintaada, rajo aan kaa qabo iyo cabsi aan kaa qabo. Majirto meel lagu magan galo oo aan adiga ahayn. Waxaan rumeeyey kitaabkaaga aad soo dejisay iyo nabigaagii aad soo dirtay.", "Wudu ka dib, u jiifso dhinaca midig - erayada ugu dambeeya hurdada ka hor.", "Hadduu habeenkaas dhinto wuxuu ku dhimanayaa fitrada (Islaamka)."),
        "dua_waking_night" to DuaText("Soo toosida Habeenkii", "Ma jiro cid xaq u leh in la caabudo Allaah mooyee, Isaga oo keliya, oo aan la wadaagin. Xukunka isagaa iska leh mahadna isagaa iska leh, wax walbana wuu karaa. Mahad oo dhan Allaah ayaa iska leh, Subxaanallaah, cid xaq u leh in la caabudo ma jirto Allaah mooyee, Allaah ayaa weyn, awood iyo xoogna ma jiro Allaah mooyee. Allahayow i cafi.", "Markaad soo toosto habeenkii.", "Ducadiisii ​​waa la ajiibay, hadduu ducaysto oo uu tukado, ducadiisu waa la aqbalayaa."),
        "dua_hamm_ibn_masud" to DuaText("Ducada Murugada (Ibnu Mascuud)", "Alloow waxaan ahay addoonkaaga, wiil addoonkaaga ah, wiilka addoontaada ah. Qoortayda gacantaaday ku jirtaa, amarkaagiina waa lagu oofiyey, Oo amarkaaguna waa xaq. Waxaan ku waydiinayaa magac kasta oo adaa leh, oo aad isku bixisay, ama aad ku soo dejisay kitaabkaaga, ama aad baray khalqigaaga mid ka mid ah, ama ku dhawrsatay naftaada ogaanshaha waxa maqan - in aad quraanka ka yeelso isha qalbigayga, nuurka laabtayda, ka saarida murugadayda iyo ka bixidda welwelkayga.", "Murugada iyo cidhiidhiga - Alle wuxuu murugada ku beddelaa farxad.", "Alle werwerka iyo murugada wuu ka qaadaa, meesheedana farxad buu ugu deeqaa."),
        "dua_difficulty_sahl" to DuaText("Marka ay wax adag yihiin", "Allahayow wax fudud ma jiro waxaan ahayn waxaad fududayso, dhibkana waad fududaynaysaa haddaad doonto.", "Marka wax la dareemo adag.", "Fududeynta imtixaannada iyo hawlaha adag."),
        "dua_musibah" to DuaText("Markay balaayo dhacdo (Istirja)", "Annagaa iska leh, isagaana u noqonaynaa. Allow iga abaal mariyo dhibka i haysta oo iigu badal mid ka fiican.", "Wixii khasaare ah ama dhibaato ah.", "Waxa hubaal ah in Eebbe wax ka khayr badan bixiyo – Umm Salamah (RA) waxa la siiyey Nebiga ﷺ."),
        "dua_debt" to DuaText("Si looga samata bixiyo deynta", "Illahow iiga filna waxaad xalaalaysay waxaad xaaraantinimaysay, fadligaadana iga yeel cid aan adiga ahayn.", "Bixinta deynta - waxaa baray Ali (RA).", "Xataa haddii dayntu tahay buur oo kale Alle ayaa dejin doona."),
        "dua_anger" to DuaText("Marka xanaaqsan", "Illahay baan ka magan galay shaydaanka la nacladay.", "Marka xanaaq.", "Nabigu ﷺ wuxuu yidhi: haduu sidaas yidhaahdo, cadhadiisu way baxaysaa."),
        "dua_waswasa" to DuaText("Ka hortagga waswaaska iimaanka", "Waxaan rumeeyey Allaah iyo Rasuulkiisa.", "Marka shaydaanka xanbaarsan iimaanku yimaado.", "Xantu markay timaaddo intaa dheh oo halkaa ku jooji (Ilaahayna ka magan gal)."),
        "dua_travel_full" to DuaText("Ducada Safarka oo Dhamaystiran", "Allahayow waxaan kugu baryeynaa safarkaan xaqqa iyo cibaadada iyo camalka aad raaliga ka tahay. Allahayow safarkaan noo fududee oo soo gaabi masaafada. Allow waxaad tahay saxaabigii safarka iyo ilaaliyaha qoyska.", "Markaad u baxayso safarka, ka dib 'Subhanalladhi sakhkhara'.", "Ducada safarka ee Sunnah oo dhamaystiran."),
        "dua_return_travel" to DuaText("Ka soo laabashada Safarka", "Waanu soo noqonaynaa, oo toobad keenaynaa, caabudaynaa oo ammaanayna Rabbigeenna.", "Ka soo laabashada safar.", "Nabigu ﷺ waxa uu sidaa yidhi mar uu safar ka soo noqday."),
        "dua_farewell_traveller" to DuaText("Sagootinta Safarka", "Waxaan Allaah idiinku wakiishay diintiina, amaanadiina iyo natiijada camalkiina.", "Marka la sagootinayo musaafurka.", "Wixii Alle loo wakiishay marna ma lumin."),
        "dua_entering_town" to DuaText("Joogsiga Meel", "Waxaan ka magan galay kalimada Eebe ee qumman xumaanta dhammaan waxa uu abuuray.", "Markaad meel joogsato ama aad timaadid magaalo cusub.", "Waxba yeeli maayo ilaa uu meeshaas ka tago."),
        "dua_boarding_ship" to DuaText("Koritaanka Markab / Gaadhi", "Magaca Eebe yaan ku billaabay doonnideedii iyo fadhigeedu. Eebahay waa dambi dhaafe Naxariista.", "Markaad fuulayso markab ama baabuur - hadalkii Nebi Nuux (AS).", "Aayad Qur'aan ah - ducada Nuux ee (AS)."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istigfar with Hayyul-Qayyum", "Waxaan danbi dhaaf waydiisanayaa Eebbaha aan ilaah kale jirin, Eebaha nool ee arsaaqa ah, isagaana ka toobad aqbalay.", "Towbad keen.", "Dembigiisa waa la dhaafaa xitaa haddii uu ka soo cararay goobta dagaalka."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir Warham", "Eebow u dambi dhaaf oo u naxariiso, adigaa u khayr badan kuwa naxariista.", "Ducada Qur'aanka - cafiska iyo naxariista.", "Aayadda ugu dambeysa ee suuradda al-Mu’minuun."),
        "dua_majlis_kaffarah" to DuaText("Kaffarat al-Majlis", "Subxaanallaah, Allow adiga ayaa mahad leh. Waxaan ka marag kacayaa inaan adiga mooyee ilaah kale jirin. Dambi dhaaf baan kaa codsanayaa, waana kuu toobad keenayaa.", "Markaad ka soo kacdo isu imaatinka.", "Waxay noqonaysaa kafaaraggud wixii khalad ah ee lagu sheegay shirka."),
        "dua_jami_forgiveness" to DuaText("Cafis Dhan", "Allahayow iga cafi gefafkayga, jahligayga, ku xad-gudubka aan ku leeyahay arrimahayga iyo wax kasta oo aad iiga aqoon badan tahay.", "Ducada Nabiga oo dhamaystiran ﷺ.", "Nabigu ﷺ ayaa ducadan samayn jiray."),
        "dua_parents_nuh" to DuaText("Ducadii Nuux (AS) ee Waalidiinta", "Eebow ii dambi dhaaf waalidkay iyo ruuxii gala gurigayga isagoo mu'miniin ah iyo dhammaan mu'miniinta rag iyo haweenba.", "Qofka waalidkiis iyo mu'miniinta.", "Ducadii Nabi Nuux (AS)."),
        "dua_shukr_parents" to DuaText("Mahadcelinta Waalidiinta & Farcanka Xaqa ah", "Eebow ii yeel inaan ku shukriyo Nicmadaada aad igu Nicmaysay aniga iyo Waalidkayba, iyo inaan Sameeyo Camal Fiican oo aad raalli ka tahay, kana yeelo Faracayda kuwo Suuban. Adiga ayaan kuu toobad keenay waxaana ka mid ahay kuwa Muslimiinta ah.", "Ducada Qur'aanka kariimka ah ee lagu gaadho afartan jir.", "Mahadnaq, camalka wanaagsan iyo xaqnimada ubadkiisa - dhamaantood waa hal duco."),
        "dua_intimacy" to DuaText("Kahor Xiriirka Guurka", "Magaca Allaah. Allahayow shaydaanka naga fogee, shaydaankana ka fogee waxa aad na siiso (caruur).", "Xiriirka guurka ka hor.", "Haddii ilmaha la xukumo, Shaydaanku waligii waxba ma yeeli doono."),
        "dua_ibrahim_children_protection" to DuaText("Ilaalinta Guriga iyo Carruurta", "Rabbiyow, magaaladan ammaan ka dhig, aniga iyo carruurtaydana ka fogow caabudidda sanamyada.", "Ducadii Nebi Ibraahim (AS) - Badbaadada magaalada iyo caruurtiisa.", "Ducada ku sii sugnaanshaha tawxiidka."),
        "dua_drinking_milk" to DuaText("Marka Caanaha la Cabayo", "Allow noo barakee oo noo siyaadi.", "Marka caanaha la cabbo.", "Caanaha ayaa ku filan cuntada iyo cabitaanka labadaba."),
        "dua_iftar_host" to DuaText("Marka la afurayo dadka kale", "Dadka sooman ha idinla afuraan, kuwa xaqa ah ha idin cunaan, Malaa'igtuna ha kuu duceeyaan.", "Marka qof gurigiisa lagu afurayo.", "Ducadii nabiga ﷺ ee martida loo yahay."),
    )
}
